"""Escapes characters you don't want in arguments (preventing shell
    injection)"""
def escapearg(args: Any) -> object {
    special_chars = '#&;`|*?~<>^()[]{}$\\';
    for char in special_chars {
        args = args.replace(char, '');
    }
    return args;
}

"""Take an integer as input and return the bits written version."""
