"""
     Get minimal value of list, version 1
    :param lst: Numbers list
    :return: Minimal value and its count on the list
    """
def min_count1(lst: Any) -> object {
    if (len(lst) == 0) {
        return [];
    }
    count = 0;
    min_value = lst[0];
    for num in lst {
        if (num == min_value) {
            count += 1;
        } elif (num < min_value) {
            count = 1;
            min_value = num;
        }
    }
    return [min_value, count];
}

"""
    Creates indices from sequences.
    :param sequences: list of sequences.
    :return: indices.
    """
def create_index_from_sequences(sequences: Any) -> object {
    indices = [];
    for index in range(0, len(sequences)) {
        indices.append(index);
    }
    return indices;
}

"""Check if all given elements are equal."""
def list_equal(*elements: Any) -> object {
    l0 = elements[0];
    for element in elements[1:] {
        if (element != l0) {
            return False;
        }
    }
    return True;
}

